// Replace with your actual table name
let table = base.getTable("Campaigns");

// Get the record ID from the input variable
let recordId = input.config().record_id;

// Fetch the specific record
let record = await table.selectRecordAsync(recordId);

// Generate a random time between 08:00 and 09:00
let morningTime = new Date();
let randomMinutesMorning = Math.floor(Math.random() * 60);
morningTime.setHours(8);
morningTime.setMinutes(randomMinutesMorning);
morningTime.setSeconds(0);
morningTime.setMilliseconds(0);

// Format to HH:mm
let formattedMorning = morningTime.toTimeString().slice(0, 5); // e.g., "08:42"

// Generate a random time between 18:00 and 19:00
let eveningTime = new Date();
let randomMinutesEvening = Math.floor(Math.random() * 60);
eveningTime.setHours(18);
eveningTime.setMinutes(randomMinutesEvening);
eveningTime.setSeconds(0);
eveningTime.setMilliseconds(0);

let formattedEvening = eveningTime.toTimeString().slice(0, 5); // e.g., "18:39"

// Update the specific record
await table.updateRecordAsync(recordId, {
    "start_time": formattedMorning,
    "end_time": formattedEvening
});

console.log(`Updated record ${recordId} with:
- Morning time: ${formattedMorning}
- Evening time: ${formattedEvening}`);

// Airtable Automation setup
// Trigger: Campaigns record matches conditions
// Condition: Trigger Automation is checked
// Input variable: recordId = Airtable record ID from the trigger

const configuredInput = input.config();
const recordId = configuredInput.recordId || configuredInput.record_id;
const WEBHOOK_URL = 'https://n8n.dulcy.io/webhook/REDACTED_PATH';
const TABLE_NAME = 'Campaigns';
const TRIGGER_FIELD_NAMES = [
    'Trigger Automation',
    'Upload to EmailBison',
    'Create EmailBison Campaign',
];

if (!recordId || !String(recordId).startsWith('rec')) {
    throw new Error('A valid Campaign recordId is required.');
}

const table = base.getTable(TABLE_NAME);
const record = await table.selectRecordAsync(recordId);
if (!record) throw new Error(`Campaign ${recordId} was not found.`);
const findField = (sourceTable, names) => {
    for (const name of names) {
        const field = sourceTable.fields.find(candidate => candidate.name === name);
        if (field) return field;
    }
    return null;
};

const triggerField = table.fields.find(field => TRIGGER_FIELD_NAMES.includes(field.name));
if (!triggerField) {
    throw new Error('The Campaigns table is missing the Trigger Automation field.');
}

// This automation uses "When a record is updated", so clearing the checkbox
// creates another update event. Ignore that reset event instead of calling n8n
// a second time.
const triggerValue = record.getCellValue(triggerField);
const isTriggered = triggerValue === true
    || (triggerValue && typeof triggerValue === 'object'
        && ['upload', 'create draft', 'requested', 'true'].includes(
            String(triggerValue.name ?? triggerValue.value ?? '').trim().toLowerCase()
        ));
if (!isTriggered) {
    output.set('started', false);
    output.set('ignored', true);
    output.set('message', 'Trigger Automation is not checked; no webhook was called.');
    return;
}

const payload = {recordId};
for (const field of table.fields) {
    payload[field.name] = record.getCellValue(field);
}

// Include the linked client's package and HeyReach settings. This avoids
// relying on Airtable lookup timing when a new campaign is created and launched
// immediately.
const clientLinkField = findField(table, ['Client / Workspace', 'Workspace', 'Workspace ID', 'Client', 'Clients', 'Client Record']);
const linkedClient = clientLinkField ? record.getCellValue(clientLinkField)?.[0] : null;
const clientsTable = base.tables.find(candidate =>
    ['Workspace IDs', 'Workspaces', 'Clients', 'Clients Table', 'Client'].includes(candidate.name)
);
if (linkedClient?.id && clientsTable) {
    const clientRecord = await clientsTable.selectRecordAsync(linkedClient.id);
    if (clientRecord) {
        payload.clientRecordId = clientRecord.id;
        payload.clientFields = {};
        for (const field of clientsTable.fields) {
            const value = clientRecord.getCellValue(field);
            payload.clientFields[field.name] = value;
            // Direct aliases let the n8n workflow use the same field names as
            // ordinary Campaign lookups, even before those lookups refresh.
            // Never alias a linked client's generic `ID`: Campaigns.ID is the
            // EmailBison campaign ID, while a client ID may be a workspace ID.
            if (value !== null && value !== undefined && field.name !== 'ID') {
                payload[field.name] ??= value;
                payload[`${field.name} (from Client)`] ??= value;
            }

            if (
                value !== null &&
                value !== undefined &&
                field.name.toLowerCase() === 'campaign_workspace_id'
            ) {
                payload.workspaceId = value;
            }
        }
    }
}

// Preserve the old uploader's explicit Lead List lookup. This makes the split
// workflow reliable even when a Campaign lookup field has not refreshed yet.
const leadListsTable = base.getTable('Lead Lists');
const linkedLeadListField = findField(table, ['Lead List', 'Campaign Lead List']);
const linkedLeadList = linkedLeadListField
    ? record.getCellValue(linkedLeadListField)?.[0]
    : null;

if (linkedLeadList?.id) {
    const leadListRecord = await leadListsTable.selectRecordAsync(linkedLeadList.id);
    if (leadListRecord) {
        payload.leadListRecordId = leadListRecord.id;
        payload.leadListName = leadListRecord.name;

        const projectSheetField = findField(leadListsTable, [
            'Project Google Sheet Link',
            'Lead List Link',
        ]);
        if (projectSheetField) {
            payload['Project Google Sheet Link (from Lead List)'] =
                leadListRecord.getCellValue(projectSheetField);
        }

        const csvField = findField(leadListsTable, ['CSV Attachment']);
        const csvAttachment = csvField ? leadListRecord.getCellValue(csvField)?.[0] : null;
        if (csvAttachment?.url) {
            payload.leadListCsvUrl = csvAttachment.url;
            payload.leadListCsvName =
                csvAttachment.filename || `${leadListRecord.name}.csv`;
        }

        const existingBisonIdField = findField(leadListsTable, [
            'EmailBison Lead List ID',
            'Bison Lead List ID',
            'Lead List ID',
        ]);
        if (existingBisonIdField) {
            payload.emailBisonLeadListId =
                leadListRecord.getCellValue(existingBisonIdField);
        }
    }
}

const response = await fetch(WEBHOOK_URL, {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify(payload),
});

const responseText = await response.text();
if (!response.ok) {
    throw new Error(`Split EmailBison upload returned HTTP ${response.status}: ${responseText || 'No response body'}`);
}

// Reset the trigger only after n8n accepts the request. This creates a clean
// false -> true transition if the operator deliberately retries later.
await table.updateRecordAsync(recordId, {
    [triggerField.id]: typeof triggerValue === 'boolean' ? false : null,
});

output.set('started', true);
output.set('recordId', recordId);
output.set('campaignName', record.name);
output.set('n8nResponse', responseText || 'Accepted');
